SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="DejaVu Sans, Arial">\n  <rect width="700" height="250" rx="10" fill="#FAFCFF" stroke="#1E3A8A" stroke-width="1.5"/>\n  <rect x="12" y="10" width="676" height="28" rx="6" fill="#1E3A8A"/>\n  <text x="350" y="29" text-anchor="middle" font-size="13" font-weight="bold" fill="#FFFFFF">İSLAM İNANCININ TEMEL KAYNAKLARI VE HADİS TASNİFİ (TDB.9.2.2)</text>\n\n  <rect x="20" y="48" width="320" height="82" rx="8" fill="#EFF6FF" stroke="#3B82F6" stroke-width="1.4"/>\n  <text x="180" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1D4ED8">1. KİTAP (KUR\'AN-I KERİM)</text>\n  <text x="32" y="84" font-size="10" fill="#1E293B">• Cebrail (a.s.) ile Hz. Muhammed\'e (s.a.v.) vahiy</text>\n  <text x="32" y="100" font-size="10" fill="#1E293B">• Tevatür yoluyla kesintisiz nakil (Hicr, 9)</text>\n  <text x="32" y="116" font-size="10" fill="#1E293B">• İnanç, ibadet, ahlak ve hukukun ilk kaynağı</text>\n\n  <rect x="360" y="48" width="320" height="82" rx="8" fill="#ECFDF5" stroke="#10B981" stroke-width="1.4"/>\n  <text x="520" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#047857">2. SÜNNET (KAVLÎ · FİİLÎ · TAKRİRÎ)</text>\n  <text x="372" y="84" font-size="10" fill="#1E293B">• Kavlî: Hz. Peygamber\'in mübarek sözleri</text>\n  <text x="372" y="100" font-size="10" fill="#1E293B">• Fiilî: Uygulama ve davranışları</text>\n  <text x="372" y="116" font-size="10" fill="#1E293B">• Takrirî: Sahabe davranışlarını onaylaması</text>\n\n  <rect x="20" y="140" width="320" height="98" rx="8" fill="#FFFBEB" stroke="#F59E0B" stroke-width="1.4"/>\n  <text x="180" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#B45309">RAVİ SAYISINA GÖRE HADİSLER</text>\n  <text x="32" y="176" font-size="10" fill="#1E293B">• Mütevatir: Her nesilde kalabalık topluluk</text>\n  <text x="32" y="194" font-size="10" fill="#1E293B">• Meşhur: Sonraki nesillerde yaygınlaşan</text>\n  <text x="32" y="212" font-size="10" fill="#1E293B">• Âhâd: Bir veya birkaç ravinin naklettiği</text>\n  <text x="32" y="228" font-size="9.5" font-weight="bold" fill="#92400E">* Akaitte Kur\'an ve mütevatir/sahih delil esastır.</text>\n\n  <rect x="360" y="140" width="320" height="98" rx="8" fill="#FDF2F8" stroke="#EC4899" stroke-width="1.4"/>\n  <text x="520" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#BE185D">SAĞLAMLIK DERECESİNE GÖRE</text>\n  <text x="372" y="176" font-size="10" fill="#1E293B">• Sahih: Güvenilir raviler, kesintisiz senet</text>\n  <text x="372" y="194" font-size="10" fill="#1E293B">• Hasen: Hafıza yönü biraz düşük, makbul</text>\n  <text x="372" y="212" font-size="10" fill="#1E293B">• Zayıf: Ravide/senette kusur bulunan</text>\n  <text x="372" y="228" font-size="9.5" font-weight="bold" fill="#9D174D">* Zayıf hadis inanç ve hükümde delil olmaz.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="DejaVu Sans, Arial">\n  <rect width="700" height="255" rx="10" fill="#FAFCFF" stroke="#065F46" stroke-width="1.5"/>\n  <rect x="12" y="10" width="676" height="28" rx="6" fill="#065F46"/>\n  <text x="350" y="29" text-anchor="middle" font-size="13" font-weight="bold" fill="#FFFFFF">İSLAM\'IN ALTI İNANÇ ESASI (ÂMENTÜ ESASLARI)</text>\n\n  <rect x="18" y="46" width="212" height="94" rx="7" fill="#ECFDF5" stroke="#10B981" stroke-width="1.3"/>\n  <text x="124" y="63" text-anchor="middle" font-size="11" font-weight="bold" fill="#047857">1. ALLAH\'A İMAN</text>\n  <text x="28" y="80" font-size="9.5" fill="#1E293B">• Tevhit ve Esmâ-i Hüsnâ</text>\n  <text x="28" y="96" font-size="9.5" fill="#1E293B">• Rabb, Melik, İlah (Nâs, 1-3)</text>\n  <text x="28" y="112" font-size="9.5" fill="#1E293B">• Zâtî ve Sübûtî Sıfatlar</text>\n  <text x="28" y="128" font-size="9.5" fill="#065F46">• İmanın özü ve ilk şartı</text>\n\n  <rect x="244" y="46" width="212" height="94" rx="7" fill="#EFF6FF" stroke="#3B82F6" stroke-width="1.3"/>\n  <text x="350" y="63" text-anchor="middle" font-size="11" font-weight="bold" fill="#1D4ED8">2. MELEKLERE İMAN</text>\n  <text x="254" y="80" font-size="9.5" fill="#1E293B">• Cebrail: Vahiy meleği</text>\n  <text x="254" y="96" font-size="9.5" fill="#1E293B">• Mikail: Tabiat olayları</text>\n  <text x="254" y="112" font-size="9.5" fill="#1E293B">• İsrafil: Sûr · Azrail: Ecel</text>\n  <text x="254" y="128" font-size="9.5" fill="#1D4ED8">• Kirâmen Kâtibîn, Hafaza</text>\n\n  <rect x="470" y="46" width="212" height="94" rx="7" fill="#FFFBEB" stroke="#F59E0B" stroke-width="1.3"/>\n  <text x="576" y="63" text-anchor="middle" font-size="11" font-weight="bold" fill="#B45309">3. KİTAPLARA İMAN</text>\n  <text x="480" y="80" font-size="9.5" fill="#1E293B">• Tevrat → Hz. Musa (a.s.)</text>\n  <text x="480" y="96" font-size="9.5" fill="#1E293B">• Zebur → Hz. Davud (a.s.)</text>\n  <text x="480" y="112" font-size="9.5" fill="#1E293B">• İncil → Hz. İsa (a.s.)</text>\n  <text x="480" y="128" font-size="9.5" fill="#B45309">• Kur\'an → Hz. Muhammed</text>\n\n  <rect x="18" y="150" width="212" height="94" rx="7" fill="#F5F3FF" stroke="#8B5CF6" stroke-width="1.3"/>\n  <text x="124" y="167" text-anchor="middle" font-size="11" font-weight="bold" fill="#6D28D9">4. PEYGAMBERLERE</text>\n  <text x="28" y="184" font-size="9.5" fill="#1E293B">• İlk: Hz. Âdem (a.s.)</text>\n  <text x="28" y="200" font-size="9.5" fill="#1E293B">• Son: Hz. Muhammed (s.a.v.)</text>\n  <text x="28" y="216" font-size="9.5" fill="#1E293B">• Sıdk, Emanet, Fetanet,</text>\n  <text x="28" y="232" font-size="9.5" fill="#6D28D9">  İsmet, Tebliğ (25 isim)</text>\n\n  <rect x="244" y="150" width="212" height="94" rx="7" fill="#FEF2F2" stroke="#EF4444" stroke-width="1.3"/>\n  <text x="350" y="167" text-anchor="middle" font-size="11" font-weight="bold" fill="#B91C1C">5. AHİRETE İMAN</text>\n  <text x="254" y="184" font-size="9.5" fill="#1E293B">• Kıyamet ve Ba\'s (Diriliş)</text>\n  <text x="254" y="200" font-size="9.5" fill="#1E293B">• Haşir, Mahşer ve Hesap</text>\n  <text x="254" y="216" font-size="9.5" fill="#1E293B">• Mizan (Adalet Terazisi)</text>\n  <text x="254" y="232" font-size="9.5" fill="#B91C1C">• Cennet ve Cehennem</text>\n\n  <rect x="470" y="150" width="212" height="94" rx="7" fill="#F0FDFA" stroke="#14B8A6" stroke-width="1.3"/>\n  <text x="576" y="167" text-anchor="middle" font-size="11" font-weight="bold" fill="#0F766E">6. KADER VE KAZAYA</text>\n  <text x="480" y="184" font-size="9.5" fill="#1E293B">• Kader: Ölçü ve plan (İlim)</text>\n  <text x="480" y="200" font-size="9.5" fill="#1E293B">• Kaza: Yaratılış (Kudret)</text>\n  <text x="480" y="216" font-size="9.5" fill="#1E293B">• Küllî ve Cüz\'î İrade</text>\n  <text x="480" y="232" font-size="9.5" fill="#0F766E">• Çalışma, Sorumluluk, Tevekkül</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="DejaVu Sans, Arial">\n  <rect width="700" height="245" rx="10" fill="#FAFCFF" stroke="#4C1D95" stroke-width="1.5"/>\n  <rect x="12" y="10" width="676" height="28" rx="6" fill="#4C1D95"/>\n  <text x="350" y="29" text-anchor="middle" font-size="13" font-weight="bold" fill="#FFFFFF">İNANÇ BAKIMINDAN İNSANLAR VE İMANIN GEÇERLİLİK ŞARTLARI</text>\n\n  <rect x="18" y="46" width="158" height="106" rx="7" fill="#ECFDF5" stroke="#10B981" stroke-width="1.3"/>\n  <text x="97" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#047857">MÜMİN</text>\n  <text x="26" y="82" font-size="9.2" fill="#1E293B">• Kalp ile tasdik,</text>\n  <text x="26" y="96" font-size="9.2" fill="#1E293B">  dil ile ikrar</text>\n  <text x="26" y="112" font-size="9.2" fill="#1E293B">• İhlas ve samimiyet</text>\n  <text x="26" y="128" font-size="9.2" fill="#1E293B">• Güven veren insan</text>\n  <text x="26" y="144" font-size="9.2" fill="#047857">  (Enfâl, 2-4)</text>\n\n  <rect x="186" y="46" width="158" height="106" rx="7" fill="#FFFBEB" stroke="#F59E0B" stroke-width="1.3"/>\n  <text x="265" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#B45309">MÜNAFIK</text>\n  <text x="194" y="82" font-size="9.2" fill="#1E293B">• Kalben inanmaz,</text>\n  <text x="194" y="96" font-size="9.2" fill="#1E293B">  diliyle inandım der</text>\n  <text x="194" y="112" font-size="9.2" fill="#1E293B">• İkiyüzlülük (Nifak)</text>\n  <text x="194" y="128" font-size="9.2" fill="#1E293B">• Yalan, sözden dönme,</text>\n  <text x="194" y="144" font-size="9.2" fill="#B45309">  emanete hıyanet</text>\n\n  <rect x="354" y="46" width="158" height="106" rx="7" fill="#FEF2F2" stroke="#EF4444" stroke-width="1.3"/>\n  <text x="433" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#B91C1C">KÂFİR VE MÜŞRİK</text>\n  <text x="362" y="82" font-size="9.2" fill="#1E293B">• Kâfir: Vahyi ve iman</text>\n  <text x="362" y="96" font-size="9.2" fill="#1E293B">  esaslarını inkâr eden</text>\n  <text x="362" y="112" font-size="9.2" fill="#1E293B">• Müşrik: Allah\'a ortak</text>\n  <text x="362" y="128" font-size="9.2" fill="#1E293B">  koşan (Şirk = Zulüm)</text>\n  <text x="362" y="144" font-size="9.2" fill="#B91C1C">  (Lokmân, 13; Nisâ, 48)</text>\n\n  <rect x="522" y="46" width="160" height="106" rx="7" fill="#F3F4F6" stroke="#6B7280" stroke-width="1.3"/>\n  <text x="602" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#374151">FASIK (FISK)</text>\n  <text x="530" y="82" font-size="9.2" fill="#1E293B">• İlahî emirlere</text>\n  <text x="530" y="96" font-size="9.2" fill="#1E293B">  itaatten ayrılan</text>\n  <text x="530" y="112" font-size="9.2" fill="#1E293B">• Büyük günahları</text>\n  <text x="530" y="128" font-size="9.2" fill="#1E293B">  alışkanlık edinen</text>\n  <text x="530" y="144" font-size="9.2" fill="#374151">  (Hucurât, 11)</text>\n\n  <rect x="18" y="162" width="664" height="72" rx="8" fill="#EEF2FF" stroke="#6366F1" stroke-width="1.3"/>\n  <text x="350" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#3730A3">İMANIN GEÇERLİ OLMASININ BEŞ TEMEL ŞARTI</text>\n  <text x="32" y="198" font-size="9.8" fill="#1E293B">1) Açık farz ve haramları inkâr etmemek   2) Kur\'an ayetlerinin bütününe inanmak (Bakara, 85)</text>\n  <text x="32" y="216" font-size="9.8" fill="#1E293B">3) Korku ve ümit (havf ve recâ) arasında olmak   4) Ölüm anına (ye\'s hâline) bırakmamak   5) Hür irade</text>\n</svg>']

